/*
 * ui_theme.c: the themes: which fonts the pages draw with, and the System 7 theme's windows and controls
 *
 * Settings > Display > Theme. The pages are written once (ui_menu.c,
 * ui_live.c, ui_pages.c, ui_overlay.c, ui_alarm.c) and a theme changes how
 * they are drawn, in three places:
 *   fonts     every F_* in ui_internal.h reads UI_FONTS for the theme in
 *             force. The System 7 fonts (src/fonts/sys7.c, generated by
 *             tools/gen_sys7.py from the art in tools/sys7/) have the line
 *             boxes of the standard ones, so a page's layout holds.
 *   the ops   ui_draw.c turns the standard theme's greys and rounded corners
 *             into black and white: dithers, square corners, and a framed
 *             window with a shadow where a page drew a card.
 *   chrome    the pieces below, which the pages ask for by name where System 7
 *             had its own way of drawing the thing: title bars, a menu's
 *             highlight, check boxes, scroll bars, dialogs and buttons.
 *
 * The System 7 theme is two-level throughout, on a 3 px grid (U): 1872 x 1404
 * is a 624 x 468 screen at three panel pixels to one. Everything it draws the
 * panel can paint in its fast two-level mode.
 */
#include "ui_internal.h"

/* Terminal and Blueprint have their own type (tools/gen_theme_fonts.py) and
 * the standard icons; Instrument is the standard type on its own ground. */
const ui_fonts_t UI_FONTS[N_THEMES] = {
    { &ui30, &ui34, &ui46, &ui60, &ui72, &ui96, &num180, &clock214, &num270, &icon34, &icon46, &icon40, &icon170 },
    { &s7_30, &s7_34, &s7_46, &s7_60, &s7_72, &s7_96, &s7_num180, &s7_clock214, &s7_num270, &s7_icon34, &s7_icon46, &s7_icon40, &s7_icon170 },
    { &tm_30, &tm_34, &tm_46, &tm_60, &tm_72, &tm_96, &tm_num180, &tm_clock214, &tm_num270, &icon34, &icon46, &icon40, &icon170 },
    { &bp_30, &bp_34, &bp_46, &bp_60, &bp_72, &bp_96, &bp_num180, &bp_clock214, &bp_num270, &icon34, &icon46, &icon40, &icon170 },
    { &ui30, &ui34, &ui46, &ui60, &ui72, &ui96, &num180, &clock214, &num270, &icon34, &icon46, &icon40, &icon170 },
};
const char *const THEMES[N_THEMES] = { "Standard", "System 7", "Terminal", "Blueprint", "Instrument" };

bool sys7(void) { return S.theme == THEME_SYS7; }
bool term(void) { return S.theme == THEME_TERM; }
bool blue(void) { return S.theme == THEME_BLUE; }
bool inst(void) { return S.theme == THEME_INST; }
bool flat(void) { return S.theme == THEME_SYS7 || S.theme == THEME_BLUE; }

/* Another theme: every page is drawn differently, so the whole screen is repainted, cleanly. */
void theme_set(int k)
{
    k = k >= 0 && k < N_THEMES ? k : 0;
    if (k == S.theme) return;
    S.theme = k;
    printf("local: theme %s\n", THEMES[k]);
    rebuild();
    local_set_dirty_full();
}

/* A window's body in the rect given: white, a one-pixel frame, and a shadow
 * along the right and the bottom inside the rect (so what repaints the rect
 * repaints the shadow). The title bar is s7_title(). */
void s7_window(layer_t *l, int x, int y, int w, int h, int style)
{
    int fw = w - U, fh = h - U;
    (void)style;
    op_fill(l, x + U, y + fh, fw, U, G_BLACK);
    op_fill(l, x + fw, y + U, U, fh, G_BLACK);
    op_fill(l, x, y, fw, fh, G_WHITE);
    op_frame(l, x, y, fw, fh, U, G_BLACK);
}

/* The title bar of the window at x, y, w wide: the title centred (an icon
 * before it when given), six lines either side and a close box when active,
 * and a small note at the right (how old a tile's data is). WIN_DARK is for a
 * card the page drew black: white words and a white rule. */
void s7_title(layer_t *l, int x, int y, int w, int style, const char *icon, const char *title, const char *tail)
{
    int fw = w - U, mid = y + (S7_TITLE_H - U) / 2;
    uint8_t fg = style == WIN_DARK ? G_WHITE : G_BLACK;
    if (style == WIN_DARK) op_fill(l, x + 4 * U, y + S7_TITLE_H - U, fw - 8 * U, U, G_WHITE);
    else op_fill(l, x, y + S7_TITLE_H - U, fw, U, G_BLACK);
    if (style == WIN_ACTIVE) {
        op_pat(l, x + 2 * U, y + 4 * U, fw - 4 * U, 11 * U, PAT_STRIPES, G_BLACK);
        op_fill(l, x + 8 * U, y + 4 * U, 13 * U, 11 * U, G_WHITE);
        op_frame(l, x + 9 * U, y + 4 * U, 11 * U, 11 * U, U, G_BLACK);
    }
    int iw = icon ? draw_font_w(F_IR, icon) + 4 * U : 0, tw = iw + draw_font_w(F_M, title), tx = x + (fw - tw) / 2;
    if (style == WIN_ACTIVE) op_fill(l, tx - 3 * U, y + 4 * U, tw + 6 * U, 11 * U, G_WHITE);
    if (icon) op_text(l, tx, mid - F_IR->line_h / 2 + 1, F_IR, fg, icon);
    op_text(l, tx + iw, mid + 14 - F_M->ascent, F_M, fg, title);          /* its capitals, 27 px, centred in the bar */
    if (tail && tail[0]) {
        int nw = draw_font_w(F_S, tail), nx = x + fw - 5 * U - nw;
        if (style == WIN_ACTIVE) op_fill(l, nx - 3 * U, y + 4 * U, nw + 6 * U, 11 * U, G_WHITE);
        op_text(l, nx, mid + 11 - F_S->ascent, F_S, fg, tail);
    }
}

/* A dialog box: the double frame of an alert. */
void s7_dialog(layer_t *l, int x, int y, int w, int h)
{
    op_fill(l, x, y, w, h, G_WHITE);
    op_frame(l, x, y, w, h, U, G_BLACK);
    op_frame(l, x + 3 * U, y + 3 * U, w - 6 * U, h - 6 * U, 2 * U, G_BLACK);
}

/* A push button's outline; the default button has the heavy ring around it. The caller writes its name. */
void s7_button(layer_t *l, int x, int y, int w, int h, bool is_default)
{
    const int r = 8 * U;
    if (is_default) {
        op_rrect_r(l, x - 4 * U, y - 4 * U, w + 8 * U, h + 8 * U, r + 4 * U, G_BLACK);
        op_rrect_r(l, x - U, y - U, w + 2 * U, h + 2 * U, r + U, G_WHITE);
    }
    op_rrect_r(l, x, y, w, h, r, G_BLACK);
    op_rrect_r(l, x + U, y + U, w - 2 * U, h - 2 * U, r - U, G_WHITE);
}

/* A check box, its right edge at xr: a square, crossed when on. On a highlighted row it is white on black. */
void s7_checkbox(layer_t *l, int xr, int cy, bool on, bool selected)
{
    const int s = 12 * U;
    int x = xr - s, y = cy - s / 2;
    uint8_t fg = selected ? G_WHITE : G_BLACK;
    op_fill(l, x, y, s, s, (uint8_t)(15 - fg));
    op_frame(l, x, y, s, s, U, fg);
    if (!on) return;
    op_line(l, x + U + 1, y + U + 1, x + s - U - 2, y + s - U - 2, U, fg);
    op_line(l, x + U + 1, y + s - U - 2, x + s - U - 2, y + U + 1, U, fg);
}

/* A scroll arrow: a solid triangle, four steps. dir: 0 up, 1 down, 2 left, 3 right. */
static void arrow(layer_t *l, int cx, int cy, int dir)
{
    for (int i = 0; i < 4; i++) {
        int half = (i + 1) * U, at = (dir == 0 || dir == 2 ? i - 2 : 1 - i) * U;
        if (dir < 2) op_fill(l, cx - half, cy + at, 2 * half, U, G_BLACK);
        else         op_fill(l, cx + at, cy - half, U, 2 * half, G_BLACK);
    }
}

/* A vertical scroll bar: an arrow at each end, a dithered track, and the box
 * where the window of `shown` rows from `top` sits in `total`. */
void s7_vscroll(layer_t *l, int x, int y, int h, int total, int top, int shown)
{
    const int w = S7_SCROLL_W;
    op_fill(l, x, y, w, h, G_WHITE);
    op_frame(l, x, y, w, h, U, G_BLACK);
    op_fill(l, x, y + w - U, w, U, G_BLACK);
    op_fill(l, x, y + h - w, w, U, G_BLACK);
    arrow(l, x + w / 2, y + w / 2, 0);
    arrow(l, x + w / 2, y + h - w / 2, 1);
    int ty = y + w, th = h - 2 * w;
    op_pat(l, x + U, ty, w - 2 * U, th, PAT_25, G_BLACK);
    if (total <= shown) return;
    int by = ty + (th - w) * top / (total - shown);
    op_fill(l, x + U, by, w - 2 * U, w, G_WHITE);
    op_frame(l, x, by - U, w, w + 2 * U, U, G_BLACK);
}

/* The same lying down, for a value: the box at num / den of the way along. */
void s7_hscroll(layer_t *l, int x, int y, int w, int num, int den)
{
    const int h = S7_SCROLL_W;
    op_fill(l, x, y, w, h, G_WHITE);
    op_frame(l, x, y, w, h, U, G_BLACK);
    op_fill(l, x + h - U, y, U, h, G_BLACK);
    op_fill(l, x + w - h, y, U, h, G_BLACK);
    arrow(l, x + h / 2, y + h / 2, 2);
    arrow(l, x + w - h / 2, y + h / 2, 3);
    int tx = x + h, tw = w - 2 * h;
    op_pat(l, tx, y + U, tw, h - 2 * U, PAT_25, G_BLACK);
    if (den <= 0) den = 1;
    int bx = tx + (int)((long)(tw - h) * clampi(num, 0, den) / den);
    op_fill(l, bx, y + U, h, h - 2 * U, G_WHITE);
    op_frame(l, bx - U, y, h + 2 * U, h, U, G_BLACK);
}

/* The screen's rounded corners: the top two on the menu bar, the bottom two on the status bar. */
void s7_corners(layer_t *l, bool top)
{
    static const int8_t STEP[5] = { 5, 3, 2, 1, 1 };
    for (int i = 0; i < 5; i++) {
        int y = top ? i * U : H - (i + 1) * U, w = STEP[i] * U;
        op_fill(l, 0, y, w, U, G_BLACK);
        op_fill(l, W - w, y, w, U, G_BLACK);
    }
}

/* ---- the boot, setup and update screens --------------------------------------
 * In the System 7 theme these are windows on the desktop, with the panel's
 * own face in them: happy while it starts, sad when it could not join the
 * WiFi (on a black desktop, as that screen was). screens.c builds the one it
 * is about to paint and draws its standard screen when this one is off. */
static layer_t L_scr;

void local_s7_screen_off(void) { L_scr.on = false; }
bool local_s7_screen_row(int y, uint8_t row[IT8951_ROW_BYTES])
{
    if (!L_scr.on) return false;
    layer_render(&L_scr, y, row);
    return true;
}

/* One line, cut to fit maxw. */
static void text_fit(layer_t *l, int x, int y, const bfont_t *f, const char *t, int maxw)
{
    char b[96]; snprintf(b, sizeof b, "%s", t);
    for (size_t k = strlen(b); k && draw_font_w(f, b) > maxw; ) b[--k] = 0;
    if (b[0]) op_text(l, x, y, f, G_BLACK, b);
}

#define SCR_X   (20 * U)                    /* the windows' left edge and width */
#define SCR_W   (W - 40 * U)
#define SCR_IN  (SCR_X + 16 * U)            /* their contents' left edge */
#define FACE_W  256

/* The boot screen: "Welcome", then the log as it happens, the newest lines of
 * the n given (each `stride` bytes apart, "" when unused). The log's window
 * starts above BOOT_LOG_Y, so the two-level repaints of the log (screens.c)
 * cover its lines and leave the welcome alone. */
void local_s7_boot(const char *sub, const char *lines, int n, int stride)
{
    layer_t *l = &L_scr;
    if (!sys7()) { l->on = false; return; }
    layer_reset(l, 0, 0, W, H, G_WHITE);
    op_pat(l, 0, 0, W, H, PAT_50, G_BLACK);
    const int y1 = 15 * U, h1 = 115 * U, y2 = 135 * U, h2 = H - y2 - 15 * U;
    s7_window(l, SCR_X, y1, SCR_W, h1, WIN_ACTIVE);
    s7_title(l, SCR_X, y1, SCR_W, WIN_ACTIVE, NULL, "Bedside", NULL);
    op_text(l, SCR_IN, y1 + S7_TITLE_H + 4 * U, &s7_face, G_BLACK, S7_HAPPY);
    int tx = SCR_IN + FACE_W + 20 * U;
    op_text(l, tx, y1 + S7_TITLE_H + 50, F_XL, G_BLACK, "Welcome to Bedside.");
    text_fit(l, tx, y1 + S7_TITLE_H + 190, F_LBL, sub, SCR_X + SCR_W - 10 * U - tx);
    s7_window(l, SCR_X, y2, SCR_W, h2, WIN_PLAIN);
    s7_title(l, SCR_X, y2, SCR_W, WIN_PLAIN, NULL, "Starting up", NULL);
    const int pitch = 13 * U, ly = y2 + S7_TITLE_H + 4 * U, fit = (y2 + h2 - 4 * U - ly) / pitch;
    int used = 0;
    for (int i = 0; i < n; i++) if (lines[(size_t)i * (size_t)stride]) used = i + 1;
    for (int i = used > fit ? used - fit : 0, k = 0; i < used; i++, k++)
        text_fit(l, SCR_X + 8 * U, ly + k * pitch, F_S, lines + (size_t)i * (size_t)stride, SCR_W - 18 * U);
}

/* WiFi setup, or (updating) new firmware loading over USB. */
void local_s7_setup(bool updating, const char *ssid, const char *why, const char *fw, bool failed)
{
    layer_t *l = &L_scr;
    if (!sys7()) { l->on = false; return; }
    layer_reset(l, 0, 0, W, H, G_WHITE);
    if (failed && !updating) op_fill(l, 0, 0, W, H, G_BLACK);
    else op_pat(l, 0, 0, W, H, PAT_50, G_BLACK);
    const int y0 = 15 * U, top = y0 + S7_TITLE_H, room = SCR_X + SCR_W - 10 * U;
    s7_window(l, SCR_X, y0, SCR_W, H - 30 * U, WIN_ACTIVE);
    s7_title(l, SCR_X, y0, SCR_W, WIN_ACTIVE, NULL, updating ? "Software update" : "WiFi setup", NULL);
    op_text(l, SCR_IN, top + 8 * U, &s7_face, G_BLACK, failed && !updating ? S7_SAD : S7_HAPPY);
    int tx = SCR_IN + FACE_W + 20 * U;
    op_text(l, tx, top + 60, F_XL, G_BLACK, updating ? "Updating firmware" : "Set up this panel");
    if (updating) {
        op_text(l, SCR_IN, top + 380, F_M, G_BLACK, "New firmware is loading over USB.");
        op_text(l, SCR_IN, top + 450, F_M, G_BLACK, "Keep the panel plugged in. It restarts by itself.");
        text_fit(l, SCR_IN, H - 15 * U - 30 * U, F_LBL, fw, room - SCR_IN);
        return;
    }
    text_fit(l, tx, top + 200, F_LBL, why, room - tx);         /* why it is here, beside the face */
    op_text(l, SCR_IN, top + 380, F_M, G_BLACK, "1   On your phone, join the WiFi network");
    text_fit(l, SCR_IN + 62, top + 450, F_XL, ssid, room - SCR_IN - 62);
    op_text(l, SCR_IN, top + 620, F_M, G_BLACK, "2   The setup page opens by itself");
    op_text(l, SCR_IN + 62, top + 682, F_LBL, G_BLACK, "or go to http://192.168.4.1");
    op_text(l, SCR_IN, top + 790, F_M, G_BLACK, "3   Choose your WiFi and your Tesserae server");
}
